mapper.update:
UPDATE ingest_run
SET heartbeat_at = now()
WHERE id = #{runId}
  AND status = 'RUNNING'
  AND attempt = #{attempt}
  AND lease_token = CAST(#{leaseToken,jdbcType=OTHER} AS uuid)

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM ingest_run
    WHERE id = #{runId}
      AND status = 'RUNNING'
      AND attempt = #{attempt}
      AND lease_token = CAST(#{leaseToken,jdbcType=OTHER} AS uuid)
)
